/// <summary>
/// PricingAttribute of table <c>RetailSalesTable</c> field RetailStoreId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
[UPSPricingAttributeFieldsDiscovery(fieldStr(RetailStoreTable, StoreNumber))]
class UPSPricingAttributeRetailSalesTableRetailStoreId extends UPSPricingAttributeRetailSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailSalesTable, RetailStoreId);
}

public Set getAllowedValues()
{
    RetailStoreTable    retailStoreTable;
    var                 ret = new Set(Types::String);

    while select StoreNumber from retailStoreTable
    {
        ret.add(retailStoreTable.StoreNumber);
    }

    return ret;
}
